/**	psfeet.c**	This file contains the PostScript Feet package.** Change History** 1990/01/06 AGR V100	Completed file.* 1991/11/24 AGR V200	Upgraded to C++.AGR	V201	1994/11/26	Minimize includes.AGR	V202	1995/08/05	Port to Symantec C++.*/#include <math.h>		// V202 cos#ifndef MAIN_ASSERT_H#include ":src:main:assert.h"	// assert#endif#ifndef PS_PSPROTO_H#include ":src:ps:psproto.h"		// PSFeet#endif#ifndef PS_PS_H#include ":src:ps:ps.h"			// ClosingLeftFirst#endif#ifndef SIGN_SIGPROTO_H#include ":src:sign:sigproto.h"	// WhichGlyph#endif#ifndef SIGN_SIGNS_H#include ":src:sign:signs.h"	// Sign#endif#define FirstCouru			(feetFirstDouble)#define LastCouru			(feetLastDouble)void PSFeet(Sign **hSign, Point pos){	int which, slant, qualifier, couru;		which = (**hSign).u.feet.which;	slant = (**hSign).u.feet.slant;	qualifier = (**hSign).u.feet.qualifier;	couru = (**hSign).u.feet.repeat;		assert(0 <= which && which <= 19 || which == feetAdlib);	assert(0 <= slant && slant <= 4);	assert(0 <= qualifier && qualifier <= 6);	assert(couru == 0 || couru == 1);	assert(which != feetAdlib || couru == 1);		if(which == feetAdlib)		PSFeetAdlib(pos);	else	{		int font, glyph;		Rect bounds;		float x, y;				WhichGlyph(*hSign, &font, &glyph, FirstPartGlyph);		GlyphBounds(font, glyph, &bounds);				x = pos.h + 0.5;		y = pos.v + 0.5;				PSFeetSign(x, y, which, slant, qualifier);				if(couru && FirstCouru <= which && which <= LastCouru)		{			int deltax;						deltax = /* bounds.right - bounds.left + feetSpaceOffset */						(int) FeetLength;						x += deltax;						PSFeetSign(x, y, which, slant, qualifier);		}	}}void PSFeetSign(float x, float y, int which, int slant, int qualifier){	float l;	static float theta[5] = {30.0, 15.0, -15.0, -30.0, 0.0};	float degrees, angle, cos_angle;		assert(0 <= which && which <= 19);	assert(0 <= slant && slant <= 4);	assert(0 <= qualifier && qualifier <= 6);		degrees = theta[slant];	angle = deg(degrees);	cos_angle = cos(angle);		l = FeetLength / cos_angle;		assert(l >= FeetLength);		PS_gsave();						/* save graphic state */		PS_translate(x, y);				/* translate to qualifier origin */	if(theta[slant])		PS_rotate(theta[slant]);	/* rotate by slant angle */	PSFeetWhich(which, l);			/* draw base sign */	PSFeetQualifier(qualifier);		/* draw qualifier */		PS_grestore();					/* restore graphic state */ }void PSFeetWhich(int which, float l){	assert(0 <= which && which <= 19);	assert(l >= FeetLength);		switch(which)	{		case First:		case ClosingLeftFirst:		case ClosingRightFirst:		case ClosingBothFirst:			PSFeetFirst(which, l);			break;				case LeftBehindThird:		case RightBehindThird:		case ClosingLeftBehindThird:		case ClosingRightBehindThird:		case ClosingRightInFrontThird:		case ClosingLeftInFrontThird:		case ClosingRightInFrontLeftBehindThird:		case ClosingLeftInFrontRightBehindThird:			PSFeetThird(which, l);			break;					case LeftBehindFifth:		case RightBehindFifth:		case ClosingLeftBehindFifth:		case ClosingRightBehindFifth:		case ClosingRightInFrontFifth:		case ClosingLeftInFrontFifth:		case ClosingRightInFrontLeftBehindFifth:		case ClosingLeftInFrontRightBehindFifth:			PSFeetFifth(which, l);			break;	}}